package main

import (
	"context"
	"log"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/ec2"
)

func handler(ctx context.Context) (interface{}, error) {
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	ec2Svc := ec2.New(sess)

	// Get all EBS Snapshots with the specified tag
	input := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("tag:backup-type"),
				Values: []*string{
					aws.String("monthly"),
					aws.String("daily"),
					aws.String("weekly"),
					aws.String("yearly"),
				},
			},
		},
	}
	snapshots, err := ec2Svc.DescribeSnapshots(input)
	if err != nil {
		log.Println(err)
		return nil, err
	}

	// Delete snapshots based on retention policy
	for _, snapshot := range snapshots.Snapshots {
		tagValue, ok := getTagValue(snapshot.Tags, "backup-type")
		if !ok {
			continue
		}

		switch *tagValue {
		case "monthly":
			keepCount := 14
			deletedSnapshots := deleteOlderSnapshots(snapshot.SnapshotId, keepCount, ec2Svc)
			log.Println("Deleted", len(deletedSnapshots), "monthly snapshots")
		case "daily":
			keepCount := 10
			deletedSnapshots := deleteOlderSnapshots(snapshot.SnapshotId, keepCount, ec2Svc)
			log.Println("Deleted", len(deletedSnapshots), "daily snapshots")
		case "weekly":
			keepCount := 4
			deletedSnapshots := deleteOlderSnapshots(snapshot.SnapshotId, keepCount, ec2Svc)
			log.Println("Deleted", len(deletedSnapshots), "weekly snapshots")
		case "yearly":
			keepCount := 1
			deletedSnapshots := deleteOlderSnapshots(snapshot.SnapshotId, keepCount, ec2Svc)
			log.Println("Deleted", len(deletedSnapshots), "yearly snapshots")
		}
	}

	return nil, nil
}

func getTagValue(tags []*ec2.Tag, key string) (*string, bool) {
	for _, tag := range tags {
		if *tag.Key == key {
			return tag.Value, true
		}
	}
	return nil, false
}

func deleteOlderSnapshots(snapshotId string, keepCount int, ec2Svc *ec2.EC2) []string {
	input := &ec2.DescribeSnapshotsInput{
		Filters: []*ec2.Filter{
			{
				Name: aws.String("snapshot-id"),
				Values: []*string{
					aws.String(snapshotId),
				},
			},
		},
	}
	snapshots, err := ec2Svc.DescribeSnapshots(input)
	if err != nil {
		log.Println(err)
		return nil
	}

	var deletedSnapshots []string
