    if (gpioInitialise() < 0) {
        std::cerr << "Error: Unable to initialize pigpio" << std::endl;
        return 1;
    }

    // Set GPIO pin 12 as an output
    gpioSetup(12, PWM_OUTPUT);

    // Set the initial state of GPIO pin 12 to LOW (0V)
    gpioWrite(12, 0);

    // Loop indefinitely and toggle the state of GPIO pin 12 every second
    while (true) {
        gpioWrite(12, 1);  // Set GPIO pin 12 to HIGH (3.3V)
        delay(1000);       // Wait 1 second
        gpioWrite(12, 0);  // Set GPIO pin 12 to LOW (0V)
